/* Auth gate — schedule-safe (headers only on manual path). */
const req = $input.first().json;
const headers = req.headers || {};
if (headers && Object.keys(headers).length > 0) {
  const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
  if (provided !== $env.CHAT_API_KEY) { return [{ json: { __error: true, status: 401, body: { ok: false, error: 'Invalid API key' } } }]; }
}
return [{ json: { ok: true } }];

/* L1 · 把 LobeHub 的关键配置固化成可重放的代码。
   现状是这些开关只存在于数据库里（当年靠临时脚本改的），一次旧备份恢复就会静默失效，
   症状是「AI 突然不听话了」——极难归因。这里让它可以被检查、也可以被修复。

   action=status（默认）：只读，返回当前值 + 漂移清单
   action=apply          ：把要求的值合并进去（只碰我们拥有的键，幂等）

   注意：每个 SQL 占位符只对应一列 —— 复用占位符会触发 pg-protocol 崩溃（见 B8 教训）。 */
const body = ($('Webhook LobeHub Config').first().json.body) || {};
const action = String(body.action || 'status').toLowerCase() === 'apply' ? 'apply' : 'status';
const { Client } = require('pg');

/* ---- 要求的不变式 ---- */
const PROVIDER_ID = 'openai';
const REQUIRED_PROVIDER = { enableResponseApi: false };           // 必须关：否则走 Responses API
const REQUIRED_AGENT = { searchMode: 'off', useModelBuiltinSearch: false, enableStreaming: true, memory: { enabled: true } };
const REQUIRED_SYSTEM_AGENT = { topic: { provider: 'openai', model: 'deepseek-chat' }, thread: { provider: 'openai', model: 'deepseek-chat' } };

const c = new Client({
  host: $env.DB_POSTGRESDB_HOST || 'postgres',
  port: Number($env.DB_POSTGRESDB_PORT || 5432),
  database: 'lobechat',
  user: $env.DB_POSTGRESDB_USER || 'n8n',
  password: $env.DB_POSTGRESDB_PASSWORD,
});

const changed = [];
const drift = [];
const j = (v) => (v && typeof v === 'object' ? v : {});

await c.connect();
try {
  /* ---------- 1. provider ---------- */
  const prov = (await c.query('SELECT id, config FROM ai_providers WHERE id = $1', [PROVIDER_ID])).rows[0] || null;
  if (!prov) {
    drift.push('provider:' + PROVIDER_ID + ':missing');
  } else {
    const cfg = j(prov.config);
    for (const k of Object.keys(REQUIRED_PROVIDER)) {
      if (cfg[k] !== REQUIRED_PROVIDER[k]) {
        drift.push('provider.' + k + '=' + JSON.stringify(cfg[k] === undefined ? null : cfg[k]));
        if (action === 'apply') {
          const merged = Object.assign({}, cfg);
          merged[k] = REQUIRED_PROVIDER[k];
          await c.query('UPDATE ai_providers SET config = $1::jsonb, updated_at = now() WHERE id = $2', [JSON.stringify(merged), PROVIDER_ID]);
          changed.push('provider.' + k);
        }
      }
    }
  }

  /* ---------- 2. agents（逐个合并 chat_config） ---------- */
  const agents = (await c.query('SELECT id, chat_config FROM agents')).rows;
  for (const a of agents) {
    const cfg = j(a.chat_config);
    const next = Object.assign({}, cfg);
    let touched = false;
    for (const k of Object.keys(REQUIRED_AGENT)) {
      if (k === 'memory') {
        const mem = j(cfg.memory);
        if (mem.enabled !== true) {
          drift.push('agent.' + a.id + '.memory.enabled');
          if (action === 'apply') { next.memory = Object.assign({}, mem, { enabled: true }); touched = true; }
        }
      } else if (cfg[k] !== REQUIRED_AGENT[k]) {
        drift.push('agent.' + a.id + '.' + k + '=' + JSON.stringify(cfg[k] === undefined ? null : cfg[k]));
        if (action === 'apply') { next[k] = REQUIRED_AGENT[k]; touched = true; }
      }
    }
    if (action === 'apply' && touched) {
      await c.query('UPDATE agents SET chat_config = $1::jsonb, updated_at = now() WHERE id = $2', [JSON.stringify(next), a.id]);
      changed.push('agent.' + a.id);
    }
  }

  /* ---------- 3. user_settings ---------- */
  const us = (await c.query('SELECT id, memory, system_agent FROM user_settings')).rows;
  for (const u of us) {
    const mem = j(u.memory);
    const sa = j(u.system_agent);
    const nextSa = Object.assign({}, sa);
    let touched = false;

    if (mem.enabled !== true) {
      drift.push('user.' + u.id + '.memory.enabled');
      if (action === 'apply') { touched = true; }
    }
    for (const slot of ['topic', 'thread']) {
      const cur = j(sa[slot]);
      const want = REQUIRED_SYSTEM_AGENT[slot];
      if (cur.model !== want.model || cur.provider !== want.provider) {
        drift.push('user.' + u.id + '.system_agent.' + slot + '=' + JSON.stringify(cur.model || null));
        if (action === 'apply') { nextSa[slot] = Object.assign({}, cur, want); touched = true; }
      }
    }
    if (action === 'apply' && touched) {
      await c.query(
        'UPDATE user_settings SET memory = $1::jsonb, system_agent = $2::jsonb, updated_at = now() WHERE id = $3',
        [JSON.stringify(Object.assign({}, mem, { enabled: true })), JSON.stringify(nextSa), u.id]
      );
      changed.push('user.' + u.id);
    }
  }

  return [{ json: {
    ok: true,
    action,
    drifted: drift.length,
    changed: changed.length,
    drift,
    changes: changed,
    summary: drift.length === 0 ? 'in sync' : (action === 'apply' ? 'healed ' + changed.length + ' item(s)' : drift.length + ' item(s) drifted (run action=apply to heal)'),
  } }];
} finally {
  await c.end().catch(() => {});
}
